get_dashboard_report_quick.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.dashboardReports().getDashboardReportQuick(Map.of(
        "duration", "last_12_months", "kpis", "total_sales,aov", "entity_name", "product"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
Map<?, ?> sales = (Map<?, ?>) body.get("sales");
System.out.println(sales.get("total") + " " + sales.get("items_sold") + " " + sales.get("average_order_value"));
for (Object row : (List<?>) body.get("kpis")) {
    Map<?, ?> kpi = (Map<?, ?>) row;
    System.out.println(kpi.get("key") + " " + kpi.get("value") + " " + kpi.get("change_percent"));
}

